use serde_json::{Value, from_str};
use std::convert::TryInto;

pub fn solve(input: Value) -> Value {
    let (cents, n) = match input.as_array() {
        Some(v) => (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()),
        None => return Value::Null,
    };

    if n <= 0 {
        return Value::Null;
    }

    let mut shares = vec![0; n as usize];
    let mut remainder = cents;

    for i in 0..n {
        let share = remainder / n;
        remainder -= share;
        shares[i as usize] = share;
    }

    for i in 0..n {
        if remainder > 0 {
            shares[i as usize] += 1;
            remainder -= 1;
        }
    }

    Value::Array(shares.into_iter().map(|s| s.into()).collect())
}
